#define OSRS242_PACKET_OUT_COUNT                                                                   \
    ((int)(sizeof(g_packet_out_definitions_osrs242) /                                              \
           sizeof(g_packet_out_definitions_osrs242[0])))

/** Canonical PKTOUT_NAME_* -> wire opcode; -1 = absent from this revision. */
static inline int
packetout_code_osrs242(int pkt_out_name)
{
    if( pkt_out_name == PKTOUT_NAME_NONE )
        return -1;
    for( int i = 0; i < OSRS242_PACKET_OUT_COUNT; i++ )
        if( g_packet_out_definitions_osrs242[i].name == pkt_out_name )
            return g_packet_out_definitions_osrs242[i].code;
    return -1;
}

/** Wire opcode -> payload size for the receiving side. 0 for an unknown
 *  opcode, which frames as empty and lets the stream resynchronise rather
 *  than desyncing on a guessed length. */
static inline int
osrs242_packetout_size(int wire_opcode)
{
    for( int i = 0; i < OSRS242_PACKET_OUT_COUNT; i++ )
        if( g_packet_out_definitions_osrs242[i].code == wire_opcode )
            return g_packet_out_definitions_osrs242[i].length;
    return 0;
}

/** Wire opcode -> canonical PKTOUT_NAME_*, or PKTOUT_NAME_NONE. */
static inline int
osrs242_packetout_name(int wire_opcode)
{
    for( int i = 0; i < OSRS242_PACKET_OUT_COUNT; i++ )
        if( g_packet_out_definitions_osrs242[i].code == wire_opcode )
            return g_packet_out_definitions_osrs242[i].name;
    return PKTOUT_NAME_NONE;
}

static inline char const*
osrs242_packetout_protname(int wire_opcode)
{
    for( int i = 0; i < OSRS242_PACKET_OUT_COUNT; i++ )
        if( g_packet_out_definitions_osrs242[i].code == wire_opcode )
            return g_packet_out_definitions_osrs242[i].prot;
    return 0;
}

